        return ("a2-scoped-baseline-table", id(value))
    if (module_name == "scripts.audit_checkpoint_e_workflows"
            and name == "_VERIFIED_ADDITIVE_PATHS"):
        # Pre-existing path-list memo, populated by the checkpoint helper
