def _scope_engine_projection() -> tuple[Any, ...]:
    module = sys.modules[__name__]
    values = vars(module)
    return tuple((name, _contract_value(values[name], include_mutable_contents=True))
                 for name in _SCOPE_ENGINE_NAMES if name in values)


